eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   CASE_STUDIES_DATA: () => (/* binding */ CASE_STUDIES_DATA)\n/* harmony export */ });\nconst CASE_STUDIES_DATA = {\n    stcp: {\n        slug: \"stcp\",\n        headline: \"Secure Trade Compliance Platform (STCP)\",\n        subtitle: \"Modernizing GEM: a 20+ year-old internal compliance tool into an intuitive, accessible, and user-friendly experience.\",\n        client: \"Secure Trade Compliance Platform (STCP)\",\n        industry: \"Financial Services\",\n        role: \"UX Researcher/Designer\",\n        platform: \"Enterprise Web Application\",\n        heroImage: \"/projects/stcp/stcp-cover.jpg\",\n        heroAlt: \"Secure Trade Compliance Platform desktop monitor display\",\n        richSections: [\n            {\n                number: \"01\",\n                title: \"Overview\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"GEM is a 20+ year-old internal platform used by employees to submit personal trade pre-clearance requests — a crucial part of maintaining compliance with financial and regulatory policies.\\n\\nOver the years, GEM had grown in complexity. The interface was outdated, cluttered, and hard to use, leading to confusion, longer review times, and accessibility challenges.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The goal of this project was to modernize GEM into an intuitive, accessible, and efficient platform — one that supports compliance integrity while making everyday tasks easier and faster for employees.\"\n                    }\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"The Challenge\",\n                blocks: [\n                    {\n                        type: \"image\",\n                        src: \"/projects/stcp/challenge-user-persona.png\",\n                        alt: \"Employee persona navigating confusing legacy compliance software\",\n                        caption: \"\",\n                        layout: \"centered-graphic\",\n                        width: 496,\n                        height: 792\n                    },\n                    {\n                        type: \"text\",\n                        content: \"How might we modernize a legacy compliance tool — known for its complexity — into a user-friendly, inclusive experience without compromising data accuracy or regulatory standards?\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"This meant improving the user experience while respecting the strict, rule-bound nature of compliance workflows. Every design change had to be precise, validated, and trustworthy.\"\n                    }\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"Goals\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Business Goals\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Maintain 100% adherence to compliance and internal policies\",\n                            \"Reduce trade review and approval time by 25%\",\n                            \"Improve employee satisfaction and reduce training dependency\",\n                            \"Strengthen the organization’s commitment to accessibility and inclusivity\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Product Goals\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Redesign GEM with a clean, modern, and intuitive interface\",\n                            \"Achieve WCAG 2.1 AA compliance across all workflows\",\n                            \"Streamline navigation to minimize task completion time\",\n                            \"Build a scalable design system for future updates and consistency\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"Research & Insights\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"To truly understand where users struggled, I collaborated with employees, reviewers, and compliance officers through:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"User interviews & surveys to uncover friction points and workflow pain areas\",\n                            \"Heuristic evaluation of the existing interface to identify usability gaps\",\n                            \"Journey mapping for trade submission and approval flows\",\n                            \"Accessibility audit to flag visual contrast issues and missing assistive support\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/stcp/research-activities.png\",\n                        alt: \"Research activities, synthesis board, and journey mapping sticky notes\",\n                        caption: \"Research Activities\",\n                        layout: \"full\",\n                        width: 1980,\n                        height: 1016\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The insights were clear — users spent too much time navigating scattered modules, key actions were often hidden, and the interface wasn’t optimized for modern devices or assistive tools.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/stcp/research-insights-diagram.png\",\n                        alt: \"Research insights breakdown and cognitive friction points diagram\",\n                        caption: \"\",\n                        layout: \"centered-graphic\",\n                        width: 806,\n                        height: 468\n                    }\n                ]\n            },\n            {\n                number: \"05\",\n                title: \"Design Approach\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"I started by co-creating a UX roadmap that broke the redesign into clear, achievable milestones.\\n\\nThrough collaborative workshops, we sketched and tested early concepts with real users, focusing on clarity, hierarchy, and ease of navigation.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The visual design system was built around simplicity and accessibility — with improved contrast, clearer typography, and responsive layouts that worked seamlessly across devices.\"\n                    }\n                ]\n            },\n            {\n                number: \"06\",\n                title: \"Testing & Iteration\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Usability testing was central to this project. Across several testing rounds, we evaluated how easily users could complete tasks, locate actions, and navigate workflows.\\n\\nKey improvements included:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Reducing excessive clicks and hidden actions\",\n                            \"Improving layout efficiency through smarter use of space\",\n                            \"Enhancing visibility of critical buttons and progress indicators\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Each iteration made the platform faster, cleaner, and easier to learn — especially for new employees.\"\n                    }\n                ]\n            },\n            {\n                number: \"07\",\n                title: \"Key Challenges\",\n                blocks: [\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Inefficient use of space: Important content was buried below the fold.\",\n                            \"Hidden actions: Users struggled to locate key buttons.\",\n                            \"Too many steps: Workflows involved unnecessary navigation.\",\n                            \"Accessibility issues: Poor color contrast and limited screen reader support.\",\n                            \"Non-responsive design: Difficult to use on mobile and smaller screens.\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Addressing these required not just design fixes, but rethinking how compliance and usability could coexist.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/stcp/old-vs-new.png\",\n                        alt: \"Visual comparison of Old legacy UI vs New modern UI\",\n                        caption: \"Old Vs New\",\n                        layout: \"full\",\n                        width: 1980,\n                        height: 1004\n                    }\n                ]\n            },\n            {\n                number: \"08\",\n                title: \"Product Outcomes & Impact\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Product Outcomes\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Reworked the STP flow to reduce visual noise, clarify primary actions, and support faster decision-making for frequent users in a regulated environment.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/stcp/stcp-before-after-outcomes.png\",\n                        alt: \"STP Experience — Before & After comparison reducing cognitive load and clarifying task workflows\",\n                        caption: \"Product Outcomes: Before & After comparison reducing cognitive load and clarifying primary actions\",\n                        layout: \"full\",\n                        width: 1024,\n                        height: 682\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Key Measurable Results\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"25% faster Task completion process\",\n                            \"50% reduction in navigation steps\",\n                            \"WCAG 2.1 AA accessibility compliance achieved\",\n                            \"Noticeably higher user satisfaction and engagement\",\n                            \"A scalable, reusable design system now powers future feature rollouts\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"09\",\n                title: \"Lessons Learned\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Modernizing a legacy system taught me how critical it is to balance innovation with compliance precision. In a regulated space, change must be thoughtful, well-documented, and validated at every step.\\n\\nEarly stakeholder alignment and inclusive user testing were key — ensuring that every improvement worked for both the end-users and the compliance teams that safeguard the system’s integrity.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/stcp/final-ui-screens.png\",\n                        alt: \"Final modernized STCP screens and component architecture\",\n                        caption: \"\",\n                        layout: \"full\",\n                        width: 1200,\n                        height: 1110\n                    }\n                ]\n            },\n            {\n                number: \"10\",\n                title: \"Reflection\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"The GEM redesign was about more than refreshing an old interface — it was about empowering employees to work confidently within a complex compliance ecosystem.\\n\\nThrough research-driven design, accessibility-first thinking, and close collaboration with stakeholders, we turned a rigid legacy tool into a modern, human-centered experience.\"\n                    }\n                ]\n            }\n        ],\n        metrics: [\n            {\n                label: \"Task Completion\",\n                value: \"25% faster\",\n                detail: \"Significant reduction in review and submission time\"\n            },\n            {\n                label: \"Navigation Steps\",\n                value: \"50% fewer\",\n                detail: \"Consolidated scattered modules into clear flows\"\n            },\n            {\n                label: \"Accessibility\",\n                value: \"WCAG 2.1 AA\",\n                detail: \"Achieved full compliance across all workflows\"\n            }\n        ]\n    },\n    ticketmitra: {\n        slug: \"ticketmitra\",\n        headline: \"TicketMitra\",\n        subtitle: \"Designing a unified, role-based platform that streamlines planning, coordination, and execution while staying inclusive and accessible.\",\n        client: \"TicketMitra / Product Manager, Developers, Business Stakeholders\",\n        industry: \"Event Tech\",\n        role: \"UX/UI Designer\",\n        platform: \"Responsive Web & Mobile\",\n        heroImage: \"/projects/ticketmitra/hero-thumbnail.png\",\n        heroAlt: \"TicketMitra event operations platform on mobile in crowd\",\n        richSections: [\n            {\n                number: \"01\",\n                title: \"Overview\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"TicketMitra is an all-in-one event management platform built to make life easier for organizers — whether they’re hosting small virtual sessions or large-scale on-ground festivals.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"My goal was simple: design a unified, role-based platform that streamlines planning, coordination, and execution while staying inclusive and accessible for everyone involved.\"\n                    }\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"The Challenge\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Event organizers often juggle multiple tools for ticketing, rides, merchandise, and on-ground logistics — leading to inefficiency and communication gaps.\\n\\nSo I asked:\\nHow might we create a single, role-based platform where organizers, owners, and ground teams can work together in real time — ensuring smooth coordination and a seamless experience for attendees, both online and offline?\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/ticketmitra/hand-holding-phone.png\",\n                        alt: \"User holding mobile device with TicketMitra app interface\",\n                        caption: \"\",\n                        layout: \"full\",\n                        width: 4000,\n                        height: 2666\n                    }\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"Objectives\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"We wanted TicketMitra to help businesses grow while making their work easier. Our key goals were:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Increase adoption – onboard 40% of target organizers in 6 months.\",\n                            \"Boost revenue – integrate ticketing, rides, and merchandise to increase per-event revenue by 25%.\",\n                            \"Improve efficiency – reduce event setup time by 30%.\",\n                            \"Build trust – create a reputation for reliable, all-in-one event management.\",\n                            \"Reach more users – support diverse event types across industries.\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"Research & Discovery\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"To understand how different teams manage events, I conducted:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"12 stakeholder interviews with organizers, owners, and on-ground officers.\",\n                            \"User journey mapping to uncover pain points across workflows.\",\n                            \"Competitive benchmarking against leading EventTech platforms to find usability gaps, especially in role-based experiences.\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"This helped me identify four key personas:\"\n                    },\n                    {\n                        type: \"list\",\n                        ordered: true,\n                        items: [\n                            \"Virtual Event Organizer – needs a smoother way to set up and track merchandise.\",\n                            \"Ride Coordinator – depends on real-time ride scheduling and attendee management.\",\n                            \"Event Owner – looks for quick insights and analytics to make data-driven decisions.\",\n                            \"Station Officer – values speed in check-ins, updates, and issue reporting.\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/ticketmitra/verified-and-organising-screens.png\",\n                        alt: \"TicketMitra Verified and Organising screens\",\n                        caption: \"Verified and Organising screen\",\n                        layout: \"centered-graphic\",\n                        width: 1500,\n                        height: 1500\n                    }\n                ]\n            },\n            {\n                number: \"05\",\n                title: \"Design Approach\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"I started by mapping each role’s unique needs to a personalized information architecture.\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Used MoSCoW prioritization with the product team to focus on the most impactful features.\",\n                            \"Created low-fidelity wireframes to validate task flows early and iterated to high-fidelity prototypes in Figma.\",\n                            \"Ensured WCAG-compliant accessibility through color contrast, clean typography, and responsive layouts for mobile and web.\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/ticketmitra/login-screen.png\",\n                        alt: \"TicketMitra Login Screen mobile mockup\",\n                        caption: \"Login Screen\",\n                        layout: \"centered-graphic\",\n                        width: 1500,\n                        height: 1500\n                    }\n                ]\n            },\n            {\n                number: \"06\",\n                title: \"Testing & Iteration\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"We ran three rounds of usability testing, each with five participants.\\nThe focus was on:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Navigation clarity\",\n                            \"Time to complete key tasks\",\n                            \"Discoverability of major features\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Based on feedback, I simplified the merchandise upload process and refined the ride-tracking interface to make real-time coordination smoother.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/ticketmitra/signup-login-process.png\",\n                        alt: \"Sign Up and Login Process user flow overview\",\n                        caption: \"Sign Up/Login Process\",\n                        layout: \"full\",\n                        width: 4586,\n                        height: 1028\n                    }\n                ]\n            },\n            {\n                number: \"07\",\n                title: \"Impact\",\n                blocks: [\n                    {\n                        type: \"list\",\n                        items: [\n                            \"30% faster event setup and coordination\",\n                            \"Increased adoption among new organizers thanks to an easier onboarding flow\",\n                            \"New revenue streams through integrated ticketing and merchandise\",\n                            \"Improved real-time updates for on-ground teams\",\n                            \"Consistent accessibility across web and mobile platforms\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"08\",\n                title: \"Lessons Learned\",\n                blocks: [\n                    {\n                        type: \"image\",\n                        src: \"/projects/ticketmitra/lessons-learned-interaction.gif\",\n                        alt: \"TicketMitra live mobile screen interaction animation\",\n                        caption: \"\",\n                        layout: \"centered-graphic\",\n                        width: 800,\n                        height: 1317,\n                        unoptimized: true\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Designing for multiple personas taught me the importance of <b>flexibility and scalability</b> in product architecture. Building inclusivity into the foundation of the system — not as an add-on — made the platform more resilient and user-friendly for everyone.\"\n                    }\n                ]\n            },\n            {\n                number: \"09\",\n                title: \"Reflection\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"TicketMitra reminded me that design is most powerful when empathy meets structure.\\n\\nBy blending research insights, collaboration, and accessibility-first thinking, I was able to craft an experience that supports every organizer — regardless of their scale, role, or event type.\"\n                    }\n                ]\n            }\n        ],\n        metrics: [\n            {\n                label: \"Setup Time\",\n                value: \"-30%\",\n                detail: \"Faster event setup and coordination workflows\"\n            },\n            {\n                label: \"Per-Event Revenue\",\n                value: \"+25%\",\n                detail: \"Via integrated ticketing, rides, and merchandise\"\n            },\n            {\n                label: \"Organizer Adoption\",\n                value: \"40%\",\n                detail: \"Target organizers onboarded within 6 months\"\n            }\n        ]\n    },\n    \"bu-super-league\": {\n        slug: \"bu-super-league\",\n        headline: \"BU Super League 2026\",\n        subtitle: \"Designed and delivered an internal sports championship platform for 1,000–1,500 Fidelity employees, leveraging AI-assisted workflows in Figma Make through to engineering handoff and internal launch.\",\n        client: \"Fidelity Investments \\xb7 Internal BU Championship\",\n        industry: \"Tech\",\n        role: \"Lead Product & UX Designer\",\n        platform: \"Internal Web App (Figma Make & Code Handoff)\",\n        heroImage: \"/projects/bu-super-league/hero-thumbnail.png\",\n        heroAlt: \"BU Super League 2026 championship portal on laptop and mobile\",\n        richSections: [\n            {\n                number: \"01\",\n                title: \"The Opportunity\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Generative AI is rapidly changing how digital products are imagined, designed, and built.\\n\\nHow might AI accelerate creative exploration while allowing human-centered design to guide product strategy, usability, and brand coherence?\\n\\nTo solve this for an active enterprise initiative, I designed BU Super League 2026—an internal championship platform engaging 1,000–1,500 Fidelity employees across regional chapters and business units. What started as an exploration combining generative AI with human UX in Figma Make progressed into an interactive prototype, engineering handoff, and an internally launched championship platform.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Rather than designing another corporate portal, I wanted to create an experience that felt high-energy, community-driven, and emotionally engaging.\\n\\nThe project became an experiment in designing not only a product, but a new design workflow—one where generative AI acts as a creative collaborator, accelerating ideation while human design judgment shapes the user journey, interaction architecture, and design system.\"\n                    },\n                    {\n                        type: \"link\",\n                        text: \"View Interactive Prototype ↗\",\n                        url: \"https://www.figma.com/make/QFbhfF82GegUrh9bF93jEC/BU-Super-League-2026-Website?fullscreen=1&t=Cb8bOfSwtTjagqfE-1&code-node-id=0-9\"\n                    }\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"The Challenge\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Employee engagement initiatives often struggle to sustain excitement. Many internal platforms prioritize administration over experience—focusing heavily on logistics while missing the emotional spark that inspires participation.\\n\\nThe challenge was twofold:\\n• First, how could an internal sports championship feel emotionally compelling, identity-driven, and memorable?\\n• Second, how could AI become a creative collaborator during product design—helping generate concepts, interface elements, and brand identities without compromising usability, consistency, or human-centered UX principles?\"\n                    }\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"Design Vision\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Instead of designing an event management portal, I envisioned a platform that felt closer to joining a professional sports league.\\n\\nThe experience needed to create anticipation, celebrate identity, and encourage participation before, during, and after each event.\\n\\nThe goal wasn't simply helping employees register. It was helping them feel like they belonged.\"\n                    }\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"My Role & Framing\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"My Role\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"I led the end-to-end product and UX design for the championship platform—collaborating with tournament organizers, establishing the design system in Figma Make, and partnering closely with our internal engineering team through handoff and launch for our 1,000–1,500 employee Business Unit at Fidelity. My responsibilities included:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Product strategy\",\n                            \"UX strategy\",\n                            \"Information architecture\",\n                            \"Interaction design\",\n                            \"Design system direction\",\n                            \"AI prompt engineering\",\n                            \"High-fidelity visual exploration\",\n                            \"Product storytelling\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"While rapid internal turnaround prioritized agile deployment, every design decision was grounded in human-centered UX principles and validated through iterative stakeholder reviews prior to production development.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Framing the Design Challenge\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Before generating a single screen, I defined the emotional experience I wanted employees to have.\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"What should employees feel throughout the journey?\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The desired progression became:\\nDiscover the championship → Register effortlessly → Choose preferred sports → Select skill level → Be assigned to a team → Celebrate team identity → Compete with colleagues → Share achievements → Return for future events.\\n\\nThis shifted the experience from completing another HR process to becoming part of a shared organizational culture.\"\n                    }\n                ]\n            },\n            {\n                number: \"05\",\n                title: \"Exploring AI as a Design Partner\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Instead of asking AI to generate random interfaces, I approached it as a collaborative design tool. Every prompt included strategic direction rather than purely visual requests. The guidance covered:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Brand personality\",\n                            \"Team identities\",\n                            \"User journeys\",\n                            \"Interaction behaviors\",\n                            \"Motion principles\",\n                            \"Responsive layouts\",\n                            \"Design system foundations\",\n                            \"Content hierarchy\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"This allowed AI to accelerate visual exploration while leaving critical product decisions in the hands of the designer.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"What AI Accelerated\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The experiment demonstrated several areas where AI significantly improved the design process:\\n\\n• Rapid concept exploration: Multiple visual directions could be explored within hours instead of days.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/bu-super-league/rapid-concept-exploration.png\",\n                        alt: \"Rapid concept exploration across sports identities and screen layouts\",\n                        caption: \"Rapid Concept Exploration\",\n                        layout: \"full\",\n                        width: 2522,\n                        height: 1518\n                    },\n                    {\n                        type: \"text\",\n                        content: \"• Brand expression & Creative momentum: AI quickly generated distinct visual identities for teams, environments, and interface themes. Rather than beginning with a blank canvas, AI provided starting points that encouraged further refinement.\\n\\n• Visual consistency: Shared prompts helped maintain a coherent design language across multiple screens.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/bu-super-league/visual-consistency.png\",\n                        alt: \"Visual consistency and cohesive component styling across league portal\",\n                        caption: \"Visual Consistency & Brand Expression\",\n                        layout: \"full\",\n                        width: 2530,\n                        height: 1500\n                    }\n                ]\n            },\n            {\n                number: \"06\",\n                title: \"Where Human Design Was Essential\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Perhaps the most valuable outcome wasn't what AI created—it was identifying where human judgment remained irreplaceable.\\n\\nUX decisions still required careful consideration around:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Information hierarchy\",\n                            \"Accessibility\",\n                            \"Interaction behavior\",\n                            \"Progressive disclosure\",\n                            \"Product strategy\",\n                            \"User psychology\",\n                            \"Enterprise feasibility\",\n                            \"Design trade-offs\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The project reinforced that while AI can generate interfaces, it cannot replace the reasoning behind meaningful user experiences.\"\n                    }\n                ]\n            },\n            {\n                number: \"07\",\n                title: \"Experience Highlights & Design Principles\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Creating emotional moments\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"One of the core objectives was transforming ordinary product interactions into memorable experiences. Instead of confirming registration with a standard success message, employees are welcomed through a cinematic house assignment sequence featuring animated emblems, dynamic lighting, celebration effects, and personalized messaging.\\n\\nThis interaction was intentionally designed to strengthen emotional investment before the competition even begins.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Extending engagement beyond the event\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Many internal sports initiatives lose momentum once matches conclude. To encourage ongoing participation, I designed the Experience Wall—a social space where employees could share match highlights, celebrate victories, post photos, react to teammates, and revisit memorable moments. This transformed the platform from a scheduling tool into a community-building experience.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Design Principles\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Design for emotion: Memorable experiences create stronger engagement than efficient workflows alone.\",\n                            \"Identity drives participation: People are more likely to contribute when they feel part of something larger than themselves.\",\n                            \"AI supports creativity—not decisions: Artificial intelligence accelerates exploration, but product strategy and user experience remain human responsibilities.\",\n                            \"Systems create consistency: A scalable design system enables innovation without sacrificing usability.\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"08\",\n                title: \"Design System\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"The visual language intentionally blended modern sports branding with enterprise usability. Key decisions included:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Dark interface optimized for immersive experiences.\",\n                            \"Bold athletic-inspired typography.\",\n                            \"Glassmorphism-inspired containers.\",\n                            \"Dynamic gradients.\",\n                            \"Animated leaderboard components.\",\n                            \"Responsive layouts across desktop and mobile.\",\n                            \"Reusable component library supporting future expansion.\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Every visual decision aimed to reinforce excitement while preserving clarity and usability.\"\n                    }\n                ]\n            },\n            {\n                number: \"09\",\n                title: \"Outcomes\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Product Outcomes\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Successfully launched an internal sports championship platform engaging 1,000–1,500 Fidelity employees.\",\n                            \"Elevated employee engagement beyond administrative logistics into a celebratory, team-first experience.\",\n                            \"Established a cohesive design system and interactive component library supporting upcoming seasons.\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Design Outcomes\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Developed an agile workflow combining AI-assisted exploration in Figma Make with robust UX standards.\",\n                            \"Proved how rapid prototyping accelerates creative momentum without sacrificing information architecture.\",\n                            \"Bridged design and engineering through clear Figma slot specifications and responsive layout guidelines.\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Personal Growth\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"This project expanded my understanding of how emerging technologies can complement—not compete with—human-centered design. It reinforced the importance of balancing innovation with critical thinking, ensuring that new tools enhance the design process without diminishing the designer's role.\"\n                    }\n                ]\n            },\n            {\n                number: \"10\",\n                title: \"Reflection\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"BU Super League fundamentally changed how I think about AI in design. Rather than viewing AI as a shortcut for generating interfaces, I began seeing it as a creative collaborator capable of accelerating exploration while leaving strategy, empathy, and decision-making firmly in human hands.\\n\\nMore importantly, the project reminded me that meaningful products are rarely defined by their visuals alone. They're defined by the experiences they create, the emotions they evoke, and the communities they help build.\\n\\nWith the platform successfully launched internally for the championship, future evolutions focus on evaluating post-tournament participant feedback, tracking multi-season engagement patterns, and refining the AI-assisted component workflow for future enterprise employee events.\"\n                    }\n                ]\n            }\n        ],\n        metrics: [\n            {\n                label: \"AI Acceleration\",\n                value: \"Workflow\",\n                detail: \"Prompt engineering paired with strategic UX direction\"\n            },\n            {\n                label: \"Team Onboarding\",\n                value: \"Cinematic\",\n                detail: \"Animated house draft and personalized identity sequence\"\n            },\n            {\n                label: \"Visual Language\",\n                value: \"Dark System\",\n                detail: \"Athletic typography, glassmorphism, responsive components\"\n            }\n        ]\n    },\n    worksite: {\n        slug: \"worksite\",\n        headline: \"Making Fieldwork Easier before the first knock on the door\",\n        subtitle: \"Restructuring complex appointment information and workflows to help field agents navigate delivery, repair and service experiences more clearly.\",\n        role: \"Experience designer\",\n        timeline: \"1 month\",\n        team: \"3 Engineers, 1 PM, 1 Product Designer\",\n        platform: \"App\",\n        client: \"Best Buy \\xb7 Worksite\",\n        industry: \"Product Design\",\n        heroImage: \"/projects/worksite/worksite-cover.png\",\n        heroAlt: \"Making Fieldwork Easier before the first knock on the door - Best Buy Worksite Case Study overview\",\n        richSections: [\n            {\n                number: \"01\",\n                title: \"Overview\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"One appointment. A lot happening behind it.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Worksite supports field teams as they move through delivery, repair, installation, and other appointment-related workflows.\\n\\nThe challenge wasn't simply redesigning an Appointment Detail Page. It was understanding what information an agent needs, when they need it, and what action should come next as an appointment moves through different stages.\\n\\nMy work focuses on restructuring that experience—from understanding the end-to-end journey and information architecture to exploring interaction patterns and evolving the experience through low- and higher-fidelity designs.\"\n                    }\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"The Challenge\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"The information was there. Finding what mattered was harder.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The Appointment Details Page (ADP) is one of the most frequently used screens inside Work Site.\\n\\nIt acts as the operational hub where technicians access customer information, products, services, notes, documentation, and workflow actions.\\n\\nAs part of a modernization initiative, leadership wanted to improve technician efficiency and reduce workflow friction across the appointment lifecycle.\\n\\nAt first, the ask sounded straightforward:\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"Redesign the Appointment Details Page.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"But after reviewing workflows and speaking with stakeholders, I realized the problem wasn't the screen itself.\\n\\nThe problem was much larger.\\n\\nAppointment Details was being used across multiple stages of a technician's journey, yet the information hierarchy remained largely static regardless of context.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"The Real Question\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"How might Appointment Details adapt to where a technician is in their workflow?\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Because what a technician needs while:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Preparing for a pre-call\",\n                            \"Leaving the warehouse\",\n                            \"Traveling to an appointment\",\n                            \"Performing a repair\",\n                            \"Completing documentation\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"...is completely different.\\n\\nThe challenge wasn't redesigning a page.\\n\\nThe challenge was designing a system that could support changing needs throughout the technician journey.\"\n                    }\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"Understanding The Journey First\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Before redesigning any screens, I mapped the complete technician workflow to understand how information needs evolve over time.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Technician Journey\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/journey-banner.png\",\n                        alt: \"Technician Journey: Pre-Call to Close for the day\",\n                        caption: \"Technician journey lifecycle progression from initial pre-call to end of day\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/journey-customer.png\",\n                        alt: \"End-to-end customer and technician journey map across Intake, Planning, Preparation, Execution, and Closure\",\n                        caption: \"End-to-End View: 13 journey stages mapping what questions and actions technicians face at each touchpoint\"\n                    }\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"What I Learned\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Three patterns emerged almost immediately.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"01 Context Changes Constantly\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Information useful during a pre-call is not the same information needed in a warehouse.\\n\\nLikewise, information needed during a repair differs from information required during appointment completion.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"02 Not Everything Deserves Equal Attention\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The existing experience surfaced large amounts of information at once.\\n\\nImportant details often competed with secondary information.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"03 The Next Action Matters More Than The Data\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Technicians don't open ADP to read information. They open it to decide:\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"What should I do next?\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/workflow-ia-crop.png\",\n                        alt: \"Workflow breakdown: Orders Assigned, Warehouse, In-Transit, Arrival, and Active Appointment contexts\",\n                        caption: \"Context mapping across order states and shifting technician priorities\"\n                    }\n                ]\n            },\n            {\n                number: \"05\",\n                title: \"Key Insight\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"The information wasn't missing. Finding what mattered was hard.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The existing experience already contained most of the information technicians needed.\\n\\nThe challenge was helping them:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Find it faster\",\n                            \"Understand it quicker\",\n                            \"Act on it confidently\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"This shifted the project from feature design to information design.\"\n                    }\n                ]\n            },\n            {\n                number: \"06\",\n                title: \"Creating A Stage-Based Information Model\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Technicians don't need all data at all times. In the field, cognitive overload directly slows service velocity.\\n\\nInstead of treating Appointment Details as a static record, I restructured it as a stage-aware operational hub categorized into distinct information layers:\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"01 \\xb7 Persistent Layer (Anchor Data — Always Present)\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Core data technicians constantly reference regardless of journey phase. Anchored at the top for immediate recognition:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>Customer Identity & Quick Contact:</strong> Name, verified phone, address, access codes.\",\n                            \"<strong>Appointment Time Window:</strong> Current scheduled arrival slot and service status.\",\n                            \"<strong>Primary Job Scope:</strong> Core work order type (Delivery, Repair, Install).\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"02 \\xb7 Contextual Layer (Stage-Aware — Dynamically Surfaced)\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Surfaces only the actions and instructions required for the technician's immediate physical stage:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>Pre-Call Stage:</strong> Customer availability confirmation, special access notes.\",\n                            \"<strong>Warehouse Departure:</strong> Part verification, staging checklist, loading confirmation.\",\n                            \"<strong>In-Transit:</strong> Turn-by-turn navigation shortcut, gate codes, running-late quick notification.\",\n                            \"<strong>On-Site Execution:</strong> Diagnosis checklist, warranty check, part replacement logging.\",\n                            \"<strong>Job Wrap-Up:</strong> Digital signature capture, payment collection, return staging.\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Appointment-Specific Information\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Changes depending on:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Delivery\",\n                            \"Repair\",\n                            \"Installation\",\n                            \"Pickup\",\n                            \"Haul Away\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Supporting Information\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Available when needed but shouldn't dominate primary tasks. Examples:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Notes\",\n                            \"Documentation\",\n                            \"Photos\",\n                            \"History\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/workflow-ia-map.png\",\n                        alt: \"Comprehensive Information Architecture and Order Lifecycle Map: 'What do I have today and what should I focus on first?'\",\n                        caption: \"Information Architecture & Order Lifecycle: Complete multi-stage mapping of technician context and actions\"\n                    }\n                ]\n            },\n            {\n                number: \"07\",\n                title: \"Design Principles\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"The resulting framework was guided by four principles.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Persistent\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Keep essential information accessible throughout the journey.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Contextual\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Adapt information based on technician needs.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Expandable\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Make supporting information available without overwhelming the primary experience.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Actionable\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Prioritize information that helps technicians decide what to do next.\"\n                    }\n                ]\n            },\n            {\n                number: \"08\",\n                title: \"Applying The Framework\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Pre-call became the first stage used to validate the model.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/purpose-callouts.png\",\n                        alt: \"Appointment details screen breakdown addressing technician purpose: Who am I calling? Why am I calling? What is the appointment about? What action should I take?\",\n                        caption: \"Appointment Details: Restructured around key technician questions during pre-call prep\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Instead of designing for every possible scenario at once, I focused on understanding how information hierarchy could better support technician goals during appointment preparation.\\n\\nThis exploration became the foundation for upcoming stages including:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Warehouse\",\n                            \"Transit\",\n                            \"Start Appointment\",\n                            \"In Appointment\",\n                            \"Completion\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Each stage uses the same underlying framework while adapting content priority and actions to match technician needs.\"\n                    }\n                ]\n            },\n            {\n                number: \"09\",\n                title: \"Example: Pre-call\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"During a pre-call, technicians are primarily trying to answer four questions:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Who am I calling?\",\n                            \"Why am I calling?\",\n                            \"What is the appointment about?\",\n                            \"What action should I take?\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The existing experience contained the required information but required excessive scanning.\\n\\nI explored:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Separating customer context from appointment context\",\n                            \"Reorganizing information around technician goals\",\n                            \"Reducing competing actions\",\n                            \"Improving content hierarchy\",\n                            \"Supporting multiple note-capture methods\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The goal was not to simplify the workflow.\\n\\nThe goal was to simplify understanding.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/screen-breakdown-callouts.png\",\n                        alt: \"Mobile UI Breakdown with 5 callouts: Customer Info Layout, Promoted to Primary CTA, Dual CTAs to Single Sticky CTA, Collapsible List Sections, Notes & Photos Section\",\n                        caption: \"Detailed UI Callouts: Key layout and interaction refinements designed to minimize friction in the field\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/appointment-details-flow.png\",\n                        alt: \"Figma Flow Canvas: Appointment details state changes, assign pre-call, pop-overs, disclosure module, and repair edge cases\",\n                        caption: \"Figma Flow Canvas: Complete state transitions, sticky pre-call action bar, and disclosure module\"\n                    }\n                ]\n            },\n            {\n                number: \"10\",\n                title: \"Outcome\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"The project established a scalable framework for how Appointment Details can evolve across the technician journey rather than being redesigned as a single isolated screen.\\n\\nSo far, the work has delivered:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Stage-based JTBDs\",\n                            \"Context-aware information hierarchy\",\n                            \"A scalable ADP framework\",\n                            \"Improved content prioritization\",\n                            \"Reduced cognitive load\",\n                            \"A foundation for future appointment stages\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Most importantly, it changed the conversation from:\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"What features should we add?\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"to\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"What information matters right now?\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/worksite/framework-evolution.png\",\n                        alt: \"Scalable ADP Framework wireframes and state variations across appointment lifecycle\",\n                        caption: \"A unified system scaling across delivery, repair, installation, and job closure\"\n                    }\n                ]\n            },\n            {\n                number: \"11\",\n                title: \"Reflection\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"One of the biggest lessons from this project was recognizing that enterprise experiences often suffer from information overload rather than missing functionality.\\n\\nBy stepping back from the screen and understanding the technician journey first, I was able to create a framework that scales across multiple workflows while preserving the behaviors technicians already know and trust.\\n\\nIn the end, this project wasn't about redesigning a page.\\n\\nIt was about designing for decision-making.\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"search-discovery\": {\n        slug: \"search-discovery\",\n        headline: \"The products weren't inconsistent. The experience was.\",\n        subtitle: \"Auditing the Product Listing Page across App and Small View to identify fragmented layout patterns, establishing module-specific spacing rules, and securing stakeholder approval for a reusable Figma slot-template framework.\",\n        client: \"Best Buy \\xb7 Search & Product Discovery\",\n        industry: \"E-Commerce Systems \\xb7 Interaction Design \\xb7 Design Systems\",\n        role: \"Product & UX Designer\",\n        platform: \"Mobile App & Small View (SV) Responsive Web\",\n        heroImage: \"/projects/search-discovery/search-discovery-cover.png\",\n        heroAlt: \"Search & Discovery PLP Experience — Small View (SV) and App View comparison mockup\",\n        richSections: [\n            {\n                number: \"01\",\n                title: \"The Situation\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"The page worked. But the experience didn't always feel connected.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"A Product Listing Page brings together multiple systems: product results, filters, sorting, sponsored content, seller information, recommendations, and merchandising.\\n\\nIndividually, these elements may function as intended. But across the page, similar information and interactions can be presented differently.\\n\\nThe challenge was not simply to introduce another feature or redesign the entire page.\\n\\n<strong>It was to identify where the mobile experience lacked consistency, clarity, or predictability.</strong>\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"The opportunity wasn't to redesign everything. It was to understand where the experience stopped behaving like one system.\"\n                    }\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"Finding the Friction: SV & App Audit\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Focusing on Small View (SV) and Native App touchpoints.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"I examined the PLP as a connected experience, looking specifically at Small View (SV) mobile web and Native App platforms where the majority of customer discovery takes place.\\n\\nAreas of investigation included:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Product information hierarchy and scanning cadence\",\n                            \"Vertical margins, card density, and gutter alignment\",\n                            \"Inconsistent divider treatments across adjacent content blocks\",\n                            \"Sponsored and promoted placement styling within organic results\",\n                            \"Third-party seller carousels and container boundary padding\"\n                        ]\n                    },\n                    {\n                        type: \"text\",\n                        content: \"The goal was to pinpoint layout inconsistencies that created cognitive friction, disrupted scanning rhythm, or made customer decisions harder.\"\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Design Question\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"<strong>Where are customers being asked to relearn patterns that should already feel familiar?</strong>\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/app-vs-web-spacing-audit.png\",\n                        alt: \"Interaction and layout density audit comparing App and Mobile Web Product Listing Pages\",\n                        caption: \"SV & App Audit: Cross-platform comparison examining vertical rhythm, separator collisions, and card layout density\",\n                        layout: \"full\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/audit-finding-1-divider-treatment.png\",\n                        alt: \"UI Audit Finding 01: Divider treatment variations between standard and sponsored product cards\",\n                        caption: \"Audit Finding 01: Inconsistent divider treatments across adjacent product cards\",\n                        layout: \"full\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/audit-finding-2-product-spacing.png\",\n                        alt: \"UI Audit Finding 02: Vertical spacing variations affecting scanning rhythm\",\n                        caption: \"Audit Finding 02: Vertical spacing variations and irregular gaps affecting scannability\",\n                        layout: \"full\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/audit-finding-3-sponsored-skus.png\",\n                        alt: \"UI Audit Finding 03: Sponsored SKU treatments and badge hierarchy within the product list\",\n                        caption: \"Audit Finding 03: Distinct treatment of sponsored SKUs competing with standard product lists\",\n                        layout: \"full\"\n                    }\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"Current vs. Expected: Audit Findings & Acceptance Criteria\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Structuring findings into clear criteria for design and engineering.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"To translate observational friction into actionable design changes, I synthesized the audit into finding cards comparing production evidence against expected source rules across Small View and App:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>01 Divider Inconsistencies:</strong> Place one single divider at the documented content boundary across SV and App view. Acceptance: A 16px divider wrapper is used once at the source boundary.\",\n                            \"<strong>02 Product Spacing Inconsistencies:</strong> Standardize product module padding to eliminate irregular scanning gaps. Acceptance: Top/right/bottom/left equals 16/16/8/16 px.\",\n                            \"<strong>04 Excessive Carousel Spacing:</strong> Review carousel module padding against the confirmed Featured rule. Acceptance: Proposed target is 16px on every side.\",\n                            \"<strong>05 Wrong Divider Usage:</strong> Standardize the visual use of trenches and dividers. Prevent divider/trench overlap or arbitrary spacing left for future content.\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/plp-audit-current-vs-expected.png\",\n                        alt: \"Current vs. Expected audit synthesis cards showing divider inconsistencies, product spacing rules, carousel padding, and trench avoidance\",\n                        caption: \"Current vs. Expected Audit Synthesis: Documenting divider inconsistencies, product spacing rules (16/16/8/16 px), carousel container padding, and trench avoidance\",\n                        layout: \"full\"\n                    }\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"Defining the Opportunity\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Not every difference is a problem.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Consistency does not mean making every component identical.\\n\\nA difference becomes worth investigating when it introduces unnecessary effort, uncertainty, or an unexpected interaction.\\n\\nI framed the audit around three questions:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>UNDERSTANDABLE</strong> — Can customers quickly recognize what they are looking at and what actions are available?\",\n                            \"<strong>PREDICTABLE</strong> — Do similar interactions behave consistently across the experience?\",\n                            \"<strong>INTENTIONAL</strong> — When patterns differ, is there a meaningful reason grounded in the customer's context?\"\n                        ]\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"Consistency matters where expectations are shared. Context matters where needs differ.\"\n                    }\n                ]\n            },\n            {\n                number: \"05\",\n                title: \"Looking Beyond Our PLP\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Researching patterns, not copying competitors.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"I reviewed comparable e-commerce experiences to understand how leading retailers approached modular listing layouts across mobile web and native apps.\\n\\nThe exploration focused on product presentation, filtering, seller information, promoted content, and discovery interactions.\\n\\nI used these references to distinguish between established conventions, emerging approaches, and context-dependent solutions that required validation before adoption.\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"Competitive research gave us reference points, not ready-made answers.\"\n                    }\n                ]\n            },\n            {\n                number: \"06\",\n                title: \"Defined Layout Rules: Module-Specific Spacing\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Tailoring layout rules to support distinct content types without sacrificing rhythm.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"Rather than enforcing an artificial, single-margin rule across incompatible components, we established module-specific spacing rules for Small View and App View:\\n\\nThese variations support different content types while preserving vertical consistency:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>Product Modules — 16px Top \\xb7 16px Right \\xb7 8px Bottom \\xb7 16px Left:</strong> The reduced 8px bottom spacing tightens visual proximity to the card's separator/boundary, preserving a scannable vertical cadence across repetitive product lists without dead space.\",\n                            \"<strong>Standard Modules — 16px on All Sides:</strong> Uniform 16px padding creates balanced breathing room for utility components, promotional banners, and filter/sort controls.\",\n                            \"<strong>Featured Modules — 16px on All Sides:</strong> Uniform 16px padding provides visual prominence for intent-driven categories, curated spotlights, or brand banners without crowding adjacent modules.\"\n                        ]\n                    },\n                    {\n                        type: \"subheading\",\n                        text: \"Large View (Desktop) Scope — Exploratory Consideration\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"<em>Large View (Desktop) is part of the broader initiative but is not the primary focus of the current work. A 24px all-around spacing rule is currently under consideration as an exploratory concept, but is NOT finalized or approved. All primary implementation and slot-template work remains concentrated on Small View and App View.</em>\"\n                    }\n                ]\n            },\n            {\n                number: \"07\",\n                title: \"Exploring Third-Party Discovery & Carousels\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Surfacing additional choices without disrupting the primary search journey.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"One key area explored within the broader PLP work was the presentation and discovery of third-party products.\\n\\nThis required balancing discoverability, information hierarchy, customer control, and container boundary spacing within the surrounding product feed.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/audit-finding-4-carousel-spacing.png\",\n                        alt: \"UI Exploration: Third-party carousel card spacing and content grouping\",\n                        caption: \"Audit Finding 04 & Exploration: Balancing carousel container spacing and 3P card density against confirmed Featured rules\",\n                        layout: \"full\"\n                    }\n                ]\n            },\n            {\n                number: \"08\",\n                title: \"Reusable Figma Slot Templates\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Evolving visual placeholders into functional component slots.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"As part of the Search & Discovery initiative at Best Buy, I developed a reusable PLP composition framework in Figma, transforming static mockup placeholders into functional component slots.\\n\\nInstead of relying on legacy INSTANCE_SWAP overrides, the library exposes Figma's native <strong>Slot property</strong>. Designers simply select the module, then place the linked content instance directly in its slot container with pre-baked padding rules.\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>Native Figma Slot Property:</strong> Direct instance insertion into responsive slots (Product, Standard, Featured) with locked padding.\",\n                            \"<strong>Embedded Reference Skeletons:</strong> Pre-assembled page skeletons that define the authorized module order before handoff.\",\n                            \"<strong>Standardized Separator Wrappers:</strong> Automated 16px divider placement at documented boundaries to prevent trench collisions.\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/figma-slot-placeholder-modules.png\",\n                        alt: \"Figma slot placeholder architecture and module-specific padding rules across Product, Standard, and Featured variants\",\n                        caption: \"Figma Slot Architecture: Module-specific padding variants (Product 16-16-8-16, Standard 16-all, Featured 16-all) with exploratory 24px desktop reference\",\n                        layout: \"full\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/figma-plp-app-template-slots.png\",\n                        alt: \"Full Product Listing Page composition: App template wireframe, populated screen with intent/sponsored slots, and component hierarchy stack\",\n                        caption: \"App PLP Slot Template: Modular component hierarchy stack, wireframe slots, and populated intent/sponsored screens\",\n                        layout: \"full\"\n                    }\n                ]\n            },\n            {\n                number: \"09\",\n                title: \"Designer Guidance & Workflow: Select → Swap → Review\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"A standardized 3-step operating guide for squad designers.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"To make adoption intuitive across multi-disciplinary squads, I created the <strong>PLP Slot Templates — Designers Usage Guide</strong> detailing an efficient 3-step workflow:\\n\\n<strong>01 SELECT:</strong> Choose the viewport template (App or Small View).\\n<strong>02 SWAP:</strong> Place linked content instance in the exposed Slot property.\\n<strong>03 REVIEW:</strong> Check the finished order against the reference skeleton and verify separator treatment before handoff.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/plp-slot-templates-designer-guide.png\",\n                        alt: \"PLP Slot Templates — Designers Usage Guide: Getting started workflow (Select, Swap, Review), App and Small View templates, Slot property mechanics, and Reference Skeleton\",\n                        caption: \"PLP Slot Templates — Designers Usage Guide: Documenting the Select → Swap → Review workflow, native Slot property usage, App + Small View wireframes, and Reference Skeleton\",\n                        layout: \"full\"\n                    }\n                ]\n            },\n            {\n                number: \"10\",\n                title: \"Designing for the Whole Page\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"A component still has to work inside a busy, full-page PLP.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"A carousel or filtering pattern cannot be evaluated only in isolation.\\n\\nIts placement and behavior affect the surrounding product results, information hierarchy, promoted content, and overall scrolling cadence.\\n\\nWe validated the slot templates across complete, full-page category matrices in Small View to ensure visual harmony across high-density and promotional shopping journeys.\"\n                    },\n                    {\n                        type: \"quote\",\n                        text: \"The goal wasn't simply to make a component more visible. It was to make it fit the whole experience.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/search-discovery/cross-product-audit-matrix.png\",\n                        alt: \"Full-page PLP audit matrix across viewports and product categories in Small View\",\n                        caption: \"Holistic PLP Matrix: Evaluating full-page vertical rhythm, spacing trenches, and content transitions in context across Small View\",\n                        layout: \"full\"\n                    }\n                ]\n            },\n            {\n                number: \"11\",\n                title: \"Outcomes & Confirmed Stakeholder Approval\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Confirmed milestone: Reusable slot template approach approved as the standard direction.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"<strong>Confirmed Project Milestone:</strong> The reusable, slot-based PLP template approach has been <strong>formally approved by product and design leadership as the standard direction for future PLP composition</strong> at Best Buy.\\n\\n<em>Framing Note: While the framework and template approach have secured confirmed stakeholder approval as the official standard direction, implementation is rolling out progressively across squads. This represents an approved architectural foundation, rather than an immediate full-scale code deployment across every product category.</em>\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"<strong>Formal Stakeholder Sign-Off:</strong> Approved standard direction for future PLP page composition across App and Small View.\",\n                            \"<strong>Eliminated Layout Guesswork:</strong> Squad designers utilize pre-configured 16/16/8/16 and 16-all slots rather than calculating ad-hoc margins.\",\n                            \"<strong>Predictable Engineering Handoff:</strong> Reference skeletons and divider rules bridge the gap between Figma components and front-end layout rendering.\",\n                            \"<strong>Consistent Customer Rhythm:</strong> A unified spacing cadence for millions of customers discovering products across Best Buy mobile touchpoints.\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"12\",\n                title: \"Reflection\",\n                blocks: [\n                    {\n                        type: \"subheading\",\n                        text: \"Consistency isn't about making everything identical.\"\n                    },\n                    {\n                        type: \"text\",\n                        content: \"This project reinforced the importance of examining the relationships between components rather than treating each screen or interaction as an isolated design problem.\\n\\nA more consistent experience comes from understanding where customers expect familiar behavior—and where context genuinely calls for something different.\\n\\n<strong>The strongest design decisions are not always about adding something new. Sometimes they're about making what already exists work better together.</strong>\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"madras-mandi\": {\n        slug: \"madras-mandi\",\n        headline: \"Madras Mandi\",\n        subtitle: \"An online marketplace bringing farm-fresh fruits and vegetables directly from farmers to consumers in Chennai.\",\n        client: \"Madras Mandi\",\n        industry: \"E-commerce / Food & Agriculture\",\n        role: \"UI Designer\",\n        platform: \"Website\",\n        heroImage: \"/projects/madras-mandi/hero-thumbnail.png\",\n        heroAlt: \"Madras Mandi MacBook mockup on desk with coffee\",\n        richSections: [\n            {\n                number: \"01\",\n                title: \"Overview\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Madras Mandi is an online marketplace bringing farm-fresh fruits and vegetables directly from farmers to consumers in Chennai. The platform emphasizes freshness, affordability, and supporting local farming communities.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/imac-overview.png\",\n                        alt: \"Madras Mandi desktop storefront interface displayed on iMac\",\n                        caption: \"\",\n                        layout: \"full\",\n                        width: 3931,\n                        height: 3840\n                    }\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"The Challenge\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"The biggest challenge was to create a complete visual identity and website interface from scratch. The client wanted an experience that felt earthy, authentic, and modern—bridging the gap between a traditional vegetable market (mandi) and a seamless digital delivery service.\"\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/laptop-challenge.png\",\n                        alt: \"Madras Mandi responsive website interface shown on laptop\",\n                        caption: \"\",\n                        layout: \"full\",\n                        width: 3872,\n                        height: 3840\n                    }\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"My Role\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"As the sole designer on this project, I:\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Crafted a new visual identity that reflects freshness and reliability.\",\n                            \"Built brand guidelines covering color, typography, iconography, and imagery style.\",\n                            \"Designed the website UI for key pages — including product listings, testimonials, and promotional sections — maintaining visual consistency and breathing room throughout.\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/laptop-box-role.png\",\n                        alt: \"Madras Mandi branded packaging box alongside laptop UI\",\n                        caption: \"\",\n                        layout: \"full\",\n                        width: 3872,\n                        height: 3840\n                    }\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"Design Highlights\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"We wanted the brand to look fresh and feel approachable.\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Chose a vibrant, organic palette inspired by fruits and vegetables.\",\n                            \"Used soft curves and subtle illustrations to make the interface feel friendly and local.\",\n                            \"Simplified product categorization so users could find essentials quickly.\",\n                            \"Placed clear, high-contrast CTAs (“Order Now”) to guide users smoothly through checkout.\"\n                        ]\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/landing-page-design.png\",\n                        alt: \"Madras Mandi full Landing Page design\",\n                        caption: \"Landing Page Design\",\n                        layout: \"full\",\n                        width: 1215,\n                        height: 3840\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/about-us-page-design.png\",\n                        alt: \"Madras Mandi About Us page design\",\n                        caption: \"About US page design\",\n                        layout: \"full\",\n                        width: 1296,\n                        height: 2333\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/how-to-order-1.png\",\n                        alt: \"How to place an order page design - 1\",\n                        caption: \"How to place an order page design - 1\",\n                        layout: \"full\",\n                        width: 1296,\n                        height: 1571\n                    },\n                    {\n                        type: \"image\",\n                        src: \"/projects/madras-mandi/how-to-order-2.png\",\n                        alt: \"How to place an order page design - 2\",\n                        caption: \"How to place an order page design - 2\",\n                        layout: \"full\",\n                        width: 1440,\n                        height: 1978\n                    }\n                ]\n            },\n            {\n                number: \"05\",\n                title: \"Impact\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"The redesign gave Madras Mandi a cohesive, modern digital identity while preserving its rustic, local warmth.\"\n                    },\n                    {\n                        type: \"list\",\n                        items: [\n                            \"Built stronger visual trust and brand recognition.\",\n                            \"Improved readability and product discoverability.\",\n                            \"Delivered an intuitive, refreshing shopping experience for farm-to-home customers.\"\n                        ]\n                    }\n                ]\n            },\n            {\n                number: \"06\",\n                title: \"Reflection\",\n                blocks: [\n                    {\n                        type: \"text\",\n                        content: \"Designing for Madras Mandi reminded me that simplicity and emotion can coexist beautifully. The goal wasn’t just to sell produce — it was to create an experience that feels as warm and natural as visiting your neighborhood market. Every design choice, from colors to whitespace, was made to build trust, celebrate freshness, and make the digital feel human.\"\n                    }\n                ]\n            }\n        ],\n        metrics: [\n            {\n                label: \"Visual Identity\",\n                value: \"End-to-End\",\n                detail: \"From brand guidelines to responsive web experience\"\n            },\n            {\n                label: \"Product Discovery\",\n                value: \"Streamlined\",\n                detail: \"Simplified categorization and high-contrast checkout\"\n            },\n            {\n                label: \"Brand Warmth\",\n                value: \"100% Organic\",\n                detail: \"Farm-to-table storytelling tailored for local communities\"\n            }\n        ]\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/data/caseStudies.ts\n");

